import java.util.*; import java.io.*; class TestClass { static class Fan implements Comparable<Fan> { String name; int quotient; Fan(String name, int quotient) { this.name = name; this.quotient = quotient; } @Override public int compareTo(Fan other) { if (this.quotient != other.quotient) { return Integer.compare(other.quotient, this.quotient); } return this.name.compareTo(other.name); } } public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String[] firstLine = br.readLine().split(" "); int n = Integer.parseInt(firstLine[0]); int t = Integer.parseInt(firstLine[1]); List<Fan> fans = new ArrayList<>(); for (int i = 0; i < n; i++) { String[] line = br.readLine().split(" "); fans.add(new Fan(line[0], Integer.parseInt(line[1]))); } Collections.sort(fans); StringBuilder sb = new StringBuilder(); for (int i = 0; i < t; i++) { sb.append(fans.get(i).name).append("\n"); } System.out.print(sb.toString()); } }